-- stg_urba_equipos_mayores — parte 1 de 1
--
-- Cada equipo que compite pasa a tener su propio registro en clubs, como ya
-- funcionan los juveniles. Sólo la categoría mayores (Superior) sigue apuntando
-- al registro de la institución.
--
-- Son 332 equipos que hoy comparten el registro de su institución. El caso que
-- lo hace visible: Newman F, Newman G y Newman H juegan el mismo torneo y los tres
-- escriben sobre club-newman, así que el motor los suma en una sola fila de la tabla.
--
-- OJO con el sufijo: es la letra del EQUIPO, no la del torneo. "Newman G" juega
-- "TOP 14 - Preintermedia F" y su triple es 9|preintermedia|G.
--
-- INSERT ... VALUES puro, ejecutable en el editor SQL. ON CONFLICT DO NOTHING.
-- NO trae el UPDATE de club_external_ids ni el INSERT en clubs: eso se arma aparte.

CREATE TABLE IF NOT EXISTS public.stg_urba_equipos_mayores (
    urba_club_id           INTEGER NOT NULL,
    categoria              TEXT    NOT NULL,
    sufijo                 TEXT    NOT NULL DEFAULT '''',
    external_id            TEXT    PRIMARY KEY,   -- el triple, tal como está en club_external_ids
    club_id_actual         TEXT    NOT NULL,      -- el registro de institución al que apunta HOY
    id_sugerido            TEXT    NOT NULL,
    nombre_sugerido        TEXT    NOT NULL,
    nombre_corto_sugerido  TEXT    NOT NULL
);

REVOKE ALL ON public.stg_urba_equipos_mayores FROM anon, authenticated;
ALTER TABLE public.stg_urba_equipos_mayores ENABLE ROW LEVEL SECURITY;

BEGIN;

ON CONFLICT (external_id) DO NOTHING;

COMMIT;

